/* Cambridge C1 Advanced · Test 1 – đề tự biên soạn theo định dạng content/exams/spec/cam-c1.json (8 phần Đọc & Use of English, 2 phần Viết, 4 phần Nghe, 4 phần Nói).
 * Không chép đề/sách. Cấu trúc: docs/specs/cambridge.md · cổng: scripts/content-qa/exam-format-check.mjs (họ cam-c1). Phần Viết đánh số tiếp sau phần Đọc. */
(self.CAMBRIDGE = self.CAMBRIDGE || []).push({
  id: "c1-t1", level: "c1", spec: "cam-c1", n: 1,
  title: "C1 Advanced · Test 1",
  rw: { parts: [
      { n: 1, type: "mcq-gap", instr: "For each question, choose the correct answer.", title: "Reclaiming the night sky", text: "Few people who live in cities have ever seen the Milky Way. Artificial lighting has become so widespread that in many urban areas the night sky is (1) to a dull orange glow, with only the brightest stars (2) to be seen. Astronomers have long complained about the problem, but it is only recently that scientists have begun to (3) its wider consequences. Migrating birds, for instance, are drawn off (4) by illuminated towers, and countless insects die circling street lamps. In response, a number of towns have (5) strict rules on outdoor lighting, requiring lamps to point downwards and to be switched off after midnight. The results have been (6) positive: energy bills have fallen, and residents report sleeping better. Campaigners are now pressing for 'dark sky reserves', protected areas where visitors can enjoy a truly black night. Such places are (7) to attract tourists, and some villages have already seen a rise in people who travel hundreds of miles simply to (8) at the stars.", items: [
        { n: 1, options: ["lowered", "cut", "reduced", "shrunk"], a: 2, cue: "to a dull orange glow", explain: "\"Reduced to\" is the fixed pattern for being brought down to a poorer state. \"Lowered\" and \"cut\" cannot be followed by \"to a dull glow\" in this sense." },
        { n: 2, options: ["succeeding", "managing", "achieving", "coping"], a: 1, cue: "only the brightest stars", explain: "\"Manage to be seen\" means to succeed in being seen. \"Succeeding\" needs \"in\", and \"achieving\" and \"coping\" do not take \"to be seen\"." },
        { n: 3, options: ["catch", "hold", "grasp", "seize"], a: 2, cue: "scientists have begun to", explain: "\"Grasp\" means to understand fully, so we \"grasp the consequences\". \"Seize\" is physical or about taking chances." },
        { n: 4, options: ["path", "way", "target", "course"], a: 3, cue: "drawn off", explain: "\"Off course\" is the fixed phrase for moving away from the right direction. The other nouns do not form this collocation." },
        { n: 5, options: ["forced", "imposed", "ordered", "ruled"], a: 1, cue: "strict rules on outdoor lighting", explain: "We \"impose\" rules on people or things. \"Forced\" and \"ordered\" are not used with \"rules\" as their object." },
        { n: 6, options: ["narrowly", "densely", "vaguely", "overwhelmingly"], a: 3, cue: "positive: energy bills have fallen", explain: "\"Overwhelmingly positive\" is a strong collocation and matches the list of good results that follows. \"Vaguely\" would weaken the point." },
        { n: 7, options: ["due", "inclined", "bound", "prone"], a: 2, cue: "to attract tourists", explain: "\"Bound to\" means almost certain to happen. \"Due to attract\" is not possible, and \"prone\" is used for unpleasant tendencies." },
        { n: 8, options: ["glance", "peep", "blink", "gaze"], a: 3, cue: "travel hundreds of miles simply to", explain: "\"Gaze at\" means to look for a long time, which suits a long journey made to enjoy the stars. A quick \"glance\" would not justify the trip." },
      ] },
      { n: 2, type: "open-gap", instr: "For each question, write the correct answer. Use only one word in each gap.", title: "Why songs stay with us", text: "Most of us can recall the words of songs we have not heard for decades, (9) it is often hard to remember what we had for lunch yesterday. Researchers believe this is (10) to the way music is processed. Rhythm and melody act as a kind of scaffolding, (11) it easier for the brain to store lyrics in the right order. (12) is more, songs are frequently linked to strong emotions, and emotional memories tend to be far (13) durable than neutral ones. This may explain (14) people with advanced dementia can sometimes sing entire songs, even though they no longer recognise their own families. Some care homes have taken advantage of this, encouraging residents to bring playlists from (15) youth. Staff report that the effect on mood can be striking, with residents who are normally silent humming along or tapping the rhythm on a table, and that, for the best (16) of an hour, patients seem more like their former selves.", items: [
        { n: 9, a: ["yet", "but", "although", "though", "while", "whereas"], cue: "songs we have not heard for decades", explain: "A linker of contrast is needed: we remember old songs, but not lunch. A word like \"so\" would show a result, which makes no sense." },
        { n: 10, a: ["due", "down", "owing"], cue: "to the way music is processed", explain: "\"Due to\", \"down to\" or \"owing to\" introduce the cause. \"Because\" would need \"of\", and so is not one word." },
        { n: 11, a: ["making"], cue: "a kind of scaffolding", explain: "A participle clause shows the result of the scaffolding: it \"makes\" storing easier. A finite verb like \"makes\" would need a subject." },
        { n: 12, a: ["what"], cue: "songs are frequently linked to strong emotions", explain: "\"What is more\" is a fixed phrase for adding a stronger point. \"That is more\" is not used." },
        { n: 13, a: ["more"], cue: "emotional memories tend to be far", explain: "\"Far more durable than\" is a comparison with \"than\" later. \"Less\" would contradict the argument that emotion helps memory." },
        { n: 14, a: ["why"], cue: "people with advanced dementia can sometimes sing", explain: "\"This may explain why\" introduces the reason for the situation that follows. \"That\" cannot follow \"explain\" here." },
        { n: 15, a: ["their"], cue: "bring playlists from", explain: "A possessive refers back to the residents: \"their youth\". \"The youth\" would mean something different." },
        { n: 16, a: ["part"], cue: "of an hour, patients seem more like", explain: "\"The best part of an hour\" is a fixed phrase meaning almost an hour. \"Half\" would not take \"best\"." },
      ] },
      { n: 3, type: "word-formation", instr: "For each question, use the word given in capitals to form a word that fits in the gap.", title: "In praise of boredom", text: "Boredom has a bad reputation, yet psychologists increasingly argue that it plays a (17) role in human creativity. When our minds are not occupied by a task, they wander, and this (18) often leads to unexpected connections between ideas. Several experiments support this view. In one, volunteers who had spent twenty minutes copying telephone numbers performed (19) better in a creative task than those who had gone straight to it. Unfortunately, modern technology offers (20) opportunities to escape dull moments: we reach for our phones the instant a queue grows (21) long. Some researchers fear that this habit makes us less (22) when we face genuine problems, and recommend that we occasionally leave our devices at home. A (23) number of schools have taken the advice to heart, introducing quiet periods in which pupils simply sit and think. Teachers say that the pupils are at first uncomfortable with the silence, but that most soon come to value it. Early results suggest that (24) levels of concentration follow.", items: [
        { n: 17, text: "(17) ___ (CENTRE)", a: ["central"], cue: "that it plays a", explain: "An adjective is needed before \"role\": \"central\" means very important. The noun \"centre\" does not fit." },
        { n: 18, text: "(18) ___ (WANDER)", a: ["wandering"], cue: "they wander, and this", explain: "\"This wandering\" is a noun referring back to the verb \"wander\". \"Wander\" cannot follow \"this\" before another verb." },
        { n: 19, text: "(19) ___ (MARK)", a: ["markedly"], cue: "copying telephone numbers performed", explain: "An adverb is needed to modify \"better\": \"markedly better\" means clearly better. \"Marked\" is an adjective." },
        { n: 20, text: "(20) ___ (END)", a: ["endless"], cue: "modern technology offers", explain: "\"Endless opportunities\" means very many. The idea of always escaping fits the noun \"opportunities\"." },
        { n: 21, text: "(21) ___ (BEAR)", a: ["unbearably"], cue: "the instant a queue grows", explain: "An adverb with a negative prefix is needed before \"long\": \"unbearably long\". \"Bearably\" would have the opposite meaning." },
        { n: 22, text: "(22) ___ (IMAGINE)", a: ["imaginative"], cue: "when we face genuine problems", explain: "After \"less\" we need an adjective, and boredom is linked to creative thinking: \"imaginative\"." },
        { n: 23, text: "(23) ___ (GROW)", a: ["growing"], cue: "number of schools have taken the advice to heart", explain: "\"A growing number\" is a fixed phrase meaning more and more. \"Grown\" would not fit before \"number\"." },
        { n: 24, text: "(24) ___ (HEIGHT)", a: ["heightened"], cue: "levels of concentration follow", explain: "\"Heightened levels\" means increased levels. The noun \"height\" or the verb \"heighten\" would not fit before \"levels\"." },
      ] },
      { n: 4, type: "transformation", instr: "For each question, complete the second sentence so that it has a similar meaning to the first sentence, using the word given. Do not change the word given. You must use between three and six words, including the word given.", items: [
        { n: 25, text: "Although she had little experience, Jo was given the manager's job.\nKEY WORD: DESPITE\nJo was given the manager's job ___ of experience.", a: ["despite her lack", "despite a lack", "despite the lack"], cue: "Although she had little experience", explain: "\"Despite\" is followed by a noun phrase, so \"lack\" replaces \"little experience\". A clause like \"despite she had\" is wrong." },
        { n: 26, text: "Nobody had expected the company to collapse so suddenly.\nKEY WORD: CAUGHT\nThe company's sudden collapse ___ guard.", a: ["caught everyone off", "caught everybody off", "caught us all off", "caught people off"], cue: "Nobody had expected the company to collapse so suddenly", explain: "\"Catch someone off guard\" means to surprise them. The sentence already ends with \"guard\", so \"off\" must finish the gap." },
        { n: 27, text: "I'd rather you didn't mention this to anyone.\nKEY WORD: PREFER\nI ___ mention this to anyone.", a: ["would prefer you not to", "would prefer you didn't", "would prefer it if you didn't", "would prefer that you didn't"], cue: "I'd rather you didn't mention this to anyone", explain: "\"Prefer someone not to do\" is the pattern. \"Would prefer you don't\" is wrong because the past form \"didn't\" or \"not to\" is needed." },
        { n: 28, text: "As soon as the meeting began, the fire alarm sounded.\nKEY WORD: SOONER\nNo ___ the fire alarm sounded.", a: ["sooner had the meeting begun than", "sooner had the meeting started than"], cue: "As soon as the meeting began", explain: "After a negative opener, we invert the subject and auxiliary: \"No sooner had ... than\". Without \"had\" the structure is wrong." },
        { n: 29, text: "They say that the minister has been involved in a scandal.\nKEY WORD: SAID\nThe minister ___ involved in a scandal.", a: ["is said to have been"], cue: "They say that the minister has been involved in a scandal", explain: "The passive reporting verb needs a perfect infinitive because the involvement is earlier than the saying. \"Is said to be\" changes the time." },
        { n: 30, text: "It doesn't matter to me which restaurant we choose.\nKEY WORD: DIFFERENCE\nIt ___ to me which restaurant we choose.", a: ["makes no difference", "does not make any difference", "doesn't make any difference"], cue: "It doesn't matter to me which restaurant we choose", explain: "\"Make no difference\" means it is not important. \"Make a difference\" would mean the opposite." },
      ] },
      { n: 5, type: "mcq", instr: "For each question, choose the correct answer.", title: "The tuner's ear", by: "An essay in which a writer remembers his grandfather.", text: [
        "My grandfather tuned pianos for forty-one years, and in all that time I never heard him play one. He would arrive at a house with a leather bag, lift the lid, strike a single note and stand perfectly still, head tilted, as though listening for a voice in another room. Customers assumed that he was assessing the damage. I came to understand, much later, that he was doing something closer to eavesdropping: the note, he said, would tell him everything about the instrument's past, from the damp of the winter before to the unkindness of a previous owner's children. Where other people heard a pleasant sound, he heard a biography, and he was seldom wrong about it.",
        "As a boy, I found this deeply irritating. Tuning, as I saw it, was a matter of turning a lever until a sound matched a fixed standard, and I could not see why it demanded such solemnity. When I said so, he did not argue. He simply handed me the lever and asked me to bring one string into agreement with its neighbour. Within a minute I was in a tangle: each time I corrected one string, another seemed to have drifted, and the harder I tried, the more the sound shimmered and wavered like heat above a road. 'You are listening for perfection,' he said, 'and there isn't any. The trick is to decide where to hide the imperfection.'",
        "It was years before I grasped what he meant. A piano cannot be tuned perfectly, because the mathematics of pitch will not allow it: if the intervals within one octave are made pure, the errors pile up elsewhere, until a chord in a distant key sounds sour. Tuners therefore spread the error thinly across the whole keyboard, so that no single chord is intolerable. The compromise, known as temperament, has shaped Western music for centuries, and few audiences ever suspect that what they hear is a carefully distributed lie. Musicians who learn of it often feel faintly cheated, as though the instrument had been keeping a secret from them. My grandfather found this neither shameful nor amusing. To him it was a form of generosity, a decision to make every key a little worse so that none of them would be unusable.",
        "I think of this whenever I am tempted to demand more of people, or of myself, than the material will bear. He was not a man who made speeches, and I doubt he would have recognised his own habit as a philosophy. Yet he carried it into everything he did: he repaired the neighbours' fences without being asked, but never mended the gate that his own cousin had broken, on the grounds that the cousin would only feel obliged to apologise. Some people called him evasive, and the neighbours were never sure whether to thank him or to be wary of him. I now suspect that he was merely practising, on human relations, the same economy of imperfection he applied to strings.",
        "After he died, I inherited the leather bag and, more reluctantly, his tuning lever, whose handle had been worn into the shape of his palm. I do not play the piano, and the lever is of no practical use to me. Still, I keep it on the shelf above my desk, and on certain evenings, when a draught is rumbling in the chimney and I am dissatisfied with something I have written, I take it down and hold it for a while. It does not make the sentence better, and it has never once told me what to write. But it reminds me to ask which flaw I can afford to live with, and that, I have found, is generally the harder and more useful question.",
      ], items: [
        { n: 31, q: "What does the writer say about his grandfather's habit of striking a single note?", options: ["It was designed to impress his customers.", "It let him find faults in the piano very quickly.", "It gave him information about the piano's history.", "It helped him judge how quiet the room was."], a: 2, cue: "tell him everything about the instrument's past", explain: "The grandfather said the note told him about the piano's past. Customers only assumed he was \"assessing the damage\", so B is the customers' view, not the truth." },
        { n: 32, q: "How did the writer react to his grandfather's approach to tuning when he was a boy?", options: ["He found the seriousness of it unnecessary.", "He was keen to learn the skill himself.", "He resented being told to wait his turn.", "He worried that he lacked musical talent."], a: 0, cue: "could not see why it demanded such solemnity", explain: "He thought tuning was simple and could not see why it needed such seriousness. Nothing says he wanted to learn at first, so B is wrong." },
        { n: 33, q: "What had the writer failed to realise when he first tried tuning?", options: ["how to hold the lever properly", "which strings were most important", "that perfect results were impossible", "that patience eventually brings accuracy"], a: 2, cue: "decide where to hide the imperfection", explain: "His grandfather said there is no perfection and that the task is to hide imperfection. The writer's trouble was not his grip or his patience, so A and D are wrong." },
        { n: 34, q: "What does the writer say about temperament?", options: ["Audiences understand it and accept it.", "It makes one octave perfectly pure.", "It spreads errors so that no chord is unbearable.", "It was invented to hide poor tuning."], a: 2, cue: "no single chord is intolerable", explain: "Temperament spreads the error across the keyboard so no chord is intolerable. Few audiences suspect it, so A is wrong." },
        { n: 35, q: "What does the writer suggest about his grandfather's behaviour towards other people?", options: ["He avoided helping his relatives.", "He sometimes ignored faults to spare people's feelings.", "He preferred to give speeches about his beliefs.", "He disliked being thanked for his kindness."], a: 1, cue: "the cousin would only feel obliged to apologise", explain: "He left the cousin's broken gate alone so the cousin would not have to apologise. He helped his neighbours, so A is wrong." },
        { n: 36, q: "What does the lever now mean to the writer?", options: ["a useful tool for his own work", "a reminder to accept some imperfections", "a possession he would rather not have", "a reason to learn to play the piano"], a: 1, cue: "which flaw I can afford to live with", explain: "It reminds him to ask which flaw he can live with. He keeps it on his shelf, so he does not resent it, and he says he does not play." },
      ] },
      { n: 6, type: "cross-text", instr: "You will read two extracts from articles about tourism in historic cities. For each question, choose the answer (A, B, C or D). Choose the answer which is correct according to the extracts.", texts: [
        { code: "A", title: "Cap the crowds", text: "When a city of fifty thousand residents receives five million visitors a year, it ceases to be a city in any meaningful sense. Rents rise, shops that serve locals give way to souvenir stands, and the very character that drew the crowds begins to evaporate. Sceptics claim that restricting numbers violates the freedom to travel, but that argument overlooks who bears the cost. Residents did not choose to share their streets with cruise-ship passengers, and nobody asked them. Those who live there pay the true price of every extra bus, every rental flat turned into a holiday let, and every quiet evening lost to the noise of a street party. A daily limit on visitors to the most fragile districts, enforced through a booking system, would be blunt but effective. Of course, it would be unpopular with hoteliers, and some would call it elitist, since only those who book early or pay more could take part. Yet an uncontrolled free-for-all is hardly egalitarian either; it merely replaces a price tag with a queue and a crush. Awareness campaigns, which many councils prefer, have a poor record. Visitors who have saved all year for a holiday are rarely persuaded to behave differently by a poster. Only a firm rule changes behaviour on the scale required, and the sooner it is introduced, the less painful it will be for everyone concerned." },
        { code: "B", title: "Teach, don't ticket", text: "Caps have an appealing simplicity, which is perhaps why they are so often proposed by people who do not have to administer them. In practice, a quota system requires armies of inspectors, invites a black market in tickets, and sends the wealthiest visitors to the front of the line. I do not deny that overcrowding is real; I have watched a lane in my own neighbourhood become impassable by ten in the morning. But the damage is caused less by numbers than by habits: tour groups that stop dead in doorways, day-trippers who leave nothing behind but litter. Habits can be changed. Elsewhere, I have seen a single well-trained guide persuade forty people to walk quietly through a cathedral in single file. Where councils have trained guides, redesigned routes to spread people across the whole city, and promoted quieter seasons, congestion has eased without anyone being turned away. Such measures may seem modest, and they certainly take longer to show results than a barrier at the gate. They do, though, treat visitors as guests rather than as a problem, and that attitude matters to people whose livelihoods depend on a welcoming reputation. A city that shuts its doors to some may find the rest reluctant to return, and few places can afford that risk." },
      ], items: [
        { n: 37, q: "Both writers agree that", options: ["tourism has weakened the local economy.", "overcrowding is a genuine problem in popular cities.", "visitor numbers are the only cause of damage.", "councils have been too slow to react."], a: 1, cue: "ceases to be a city in any meaningful sense… I do not deny that overcrowding is real", explain: "Writer A describes a city losing its character, and writer B admits overcrowding is real. Writer B says numbers are not the main cause, so C is wrong." },
        { n: 38, q: "How do the writers differ in their attitude to measures that change visitors' habits?", options: ["A thinks they achieve little, whereas B thinks they can work.", "A thinks they are too costly, whereas B thinks they are fair.", "A thinks they are unfair, whereas B thinks they are cheap.", "A thinks they are unnecessary, whereas B thinks they are urgent."], a: 0, cue: "have a poor record… congestion has eased without anyone being turned away", explain: "A says awareness campaigns have a poor record, while B says guides and routes have eased congestion. Neither writer discusses cost or urgency." },
        { n: 39, q: "What do both writers do when presenting their own proposals?", options: ["They quote research from a number of cities.", "They accuse local councils of neglect.", "They admit that the proposal has drawbacks.", "They suggest it would be popular with residents."], a: 2, cue: "some would call it elitist… they certainly take longer to show results", explain: "A concedes that a cap is unpopular and elitist, and B accepts that his measures are slow. Neither quotes research, so A is wrong." },
        { n: 40, q: "In response to writer A's remark that an uncontrolled free-for-all is 'hardly egalitarian', writer B would probably argue that", options: ["a quota system would not be fairer either.", "hoteliers should decide who may visit.", "residents should pay for crowd control.", "queues are the fairest solution of all."], a: 0, cue: "hardly egalitarian either… sends the wealthiest visitors to the front of the line", explain: "B says quotas send the wealthiest visitors to the front of the line, so caps are not fair either. B does not mention hoteliers or residents paying." },
      ] },
      { n: 7, type: "gapped-text", instr: "Six sentences have been removed from the text. Choose from the sentences A–G the one which fits each gap (41–46). There is one extra sentence which you do not need to use.", title: "Listening to the sea", by: "A magazine article about counting whales by sound.", text: [
        "For most of the twentieth century, the only way to count whales was to look for them. Whalers had once kept careful logbooks, but those records were hardly a basis for science. Observers on ships and aircraft scanned the horizon for the telltale spout, and their tallies, however painstaking, were bound to miss animals that stayed deep or surfaced when no one was watching. (41) Marine acoustician Ines Calloway believes that the answer lies not in watching the sea but in listening to it.",
        "Whales are, after all, among the noisiest creatures on Earth. Fin whales produce low pulses that can travel hundreds of kilometres through the water, and humpbacks sing complex songs that change from year to year, and some species can be heard from across an entire ocean basin. (42) Calloway's team now anchors waterproof microphones to the seabed, where they record continuously for up to eighteen months without anyone being present.",
        "The recordings, however, produce a new difficulty: enormous quantities of data. A single microphone may collect several terabytes in a season, far more than any human could listen to; at the start of the project, the team estimated that it would take a lifetime to work through the first season alone. (43) The software works by recognising the shape of a call on a picture of the sound called a spectrogram, much as a face is recognised in a photograph.",
        "Early results have already surprised the researchers. In one area off the coast of Iceland, the microphones picked up blue whales in winter, a season when the animals were believed to have migrated south. The recordings were clear and unmistakable, and the calls continued for several weeks. (44) 'We assumed we knew where they went and when,' Calloway says. 'It turns out we knew rather less than we thought.'",
        "The same technology is proving valuable in a less welcome way. Shipping noise has risen steadily since the 1960s, and the recordings show whales calling more loudly, or falling silent altogether, when a large vessel passes. In busy shipping lanes, the sea has become so noisy that whales may be unable to hear one another over distances that were once routine. (45) Some shipping firms have already responded by agreeing to slow down in busy areas, which cuts both noise and fuel costs.",
        "Not everyone is convinced that listening can replace looking. Critics point out that a silent whale cannot be counted, and that call rates vary with the season, the time of day and the animal's mood. (46) For that reason, Calloway insists that her method should be used alongside traditional surveys and not instead of them. 'The two approaches make up for each other's blind spots,' she says.",
      ], options: [
        "A Calloway herself grew up far from the coast and had never seen a whale until she was twenty.",
        "B To cope with this, the team trained a computer program to pick out whale calls from the background noise of waves, ships and rain.",
        "C That left scientists with estimates that could be wrong by a factor of two or more.",
        "D It is an objection Calloway takes seriously, since the link between the number of calls and the number of animals is still imperfectly understood.",
        "E Visual surveys had simply never been carried out there in the dark months, so no one had noticed.",
        "F Such sounds, unlike spouts, can be detected by day or night, in fog or in storms.",
        "G Evidence of this kind has proved far more persuasive to policymakers than any amount of general concern.",
      ], items: [
        { n: 41, text: "Gap 41", a: "C", cue: "bound to miss animals that stayed deep", explain: "Sentence C states the result of the missed animals: unreliable estimates. Then Calloway's different approach is introduced. Sentence A is extra and does not follow from the tallies." },
        { n: 42, text: "Gap 42", a: "F", cue: "humpbacks sing complex songs that change from year to year", explain: "\"Such sounds\" refers to the pulses and songs, and \"unlike spouts\" links back to the first paragraph. Then the microphones are introduced as the solution." },
        { n: 43, text: "Gap 43", a: "B", cue: "far more than any human could listen to", explain: "Sentence B offers the answer to the data problem, and \"the software\" in the next sentence refers to the computer program it mentions." },
        { n: 44, text: "Gap 44", a: "E", cue: "believed to have migrated south", explain: "Sentence E explains why the winter presence of blue whales was a surprise. Calloway's \"We assumed we knew\" then comments on that." },
        { n: 45, text: "Gap 45", a: "G", cue: "Some shipping firms have already responded", explain: "\"Evidence of this kind\" refers to the recordings of whales reacting to ships. It explains why shipping firms have responded." },
        { n: 46, text: "Gap 46", a: "D", cue: "a silent whale cannot be counted", explain: "Sentence D responds to the critics' objection, and \"For that reason\" then gives Calloway's conclusion. Sentence A would not link to either." },
      ] },
      { n: 8, type: "matching", instr: "For each question, choose from the sections A–D. The sections may be chosen more than once. Four scientists write about a time when a project did not go to plan.", texts: [
        { code: "A", title: "Mira Halloran, geologist", text: "For nine years I collected samples from a remote glacier in Patagonia, carrying them down in a rucksack and cataloguing each one by hand. The night before I was due to analyse the whole set, a power cut corrupted the only drive on which the records were stored. I had never made a second copy, partly out of laziness and partly because the data seemed too precious to let out of my sight, which, with hindsight, was precisely the wrong reason. For weeks I could barely speak about it. Then a colleague pointed out that the samples themselves were still intact, and that most of the cataloguing was, in effect, stored in my memory. It was a humbling thing to hear. I rebuilt the record in a year, working evenings and weekends, and the second version was, I admit, better organised than the first. These days I back up everything in three places and insist that my students do the same. What I did not expect was that losing everything would make me less afraid of loss: I now take risks with new projects that I would never have attempted before." },
        { code: "B", title: "Tomas Reyes, chemist", text: "My team spent two years trying to develop a glue that would work underwater. When we finally produced a sample, it failed every test: it was weak, brittle and, to make matters worse, it peeled away from every surface we tried. I wrote the project off, apologised to my funders and moved on to other work. Several months later, a visiting researcher from a hospital laboratory noticed a tub of the stuff on a shelf and asked whether it could be peeled off cleanly. It could, and that, it turned out, was exactly what surgeons needed: a dressing that holds for an hour but leaves no damage when removed. The product is now in clinical trials, and a company has offered to make it in quantity. I am often asked what lesson I draw, and I answer that a result is only a failure relative to the question you asked. Had I thrown the tub away, as my assistant wanted to, nobody would ever have known. I have since pinned a note on my office door that reads 'ask a different question'." },
        { code: "C", title: "Aiko Nakamura, psychologist", text: "Three years ago I published a study suggesting that people make kinder decisions after a short walk in a park. It was widely reported, and I enjoyed a brief period of fame, including an invitation to appear on the radio. Then another laboratory tried to repeat the experiment and found no effect at all. My first instinct was to defend my results, and I drafted several angry replies, none of which I sent, mostly because my partner confiscated my laptop. Eventually I re-examined my own data and saw that my sample had been too small to support the claim. I wrote to the journal and published a correction, in which I said plainly that my conclusion had been wrong. Colleagues were divided: some praised me, while a few warned that admitting error would damage my career. As it happens, my grant applications have gone better since, not worse, perhaps because reviewers trust a scientist who has shown she can say 'I was mistaken'. I now spend a whole lecture on the replication crisis, because I believe students should learn about failure before they experience it." },
        { code: "D", title: "Samuel Okoye, ecologist", text: "In the third year of my fieldwork on wetland birds, a flood washed away most of my nesting boxes and, with them, a season's results. I was devastated, but the villagers who lived beside the marsh were not. They had seen floods before, and they simply asked how they could help. Over the following weeks, a dozen of them rebuilt the boxes, and some began recording observations that I had never thought to ask for: when the frogs started calling, which fields the geese preferred, and where the water first appeared after heavy rain. I had previously regarded local people as a source of permission rather than of knowledge, and I am embarrassed to say so. Their notes, which reach back several decades and are written in careful pencil, have since become the backbone of my paper. We now share authorship, a practice that is still unusual in my field and that some of my peers consider eccentric. Perhaps it is. But I would rather be eccentric than be someone who never learned to listen." },
      ], items: [
        { n: 47, text: "admits that a lack of care contributed to a serious loss", a: "A", cue: "partly out of laziness", explain: "Mira says she never made a second copy \"partly out of laziness\". No other writer blames their own carelessness for the setback." },
        { n: 48, text: "has become more willing to take chances since the setback", a: "A", cue: "I now take risks with new projects", explain: "Mira says that losing everything made her less afraid of loss, so she takes risks. Aiko's result improved, but she does not say she takes more risks." },
        { n: 49, text: "discovered that an apparent failure suited a purpose nobody had planned", a: "B", cue: "exactly what surgeons needed", explain: "Tomas's useless glue turned out to be ideal for surgical dressings. This was an unplanned use." },
        { n: 50, text: "might have lost something valuable if a colleague's wish had been followed", a: "B", cue: "as my assistant wanted to", explain: "Tomas says that throwing the tub away, which his assistant wanted, would have meant no one ever knew. He kept it." },
        { n: 51, text: "was tempted to react defensively when a result was challenged", a: "C", cue: "My first instinct was to defend my results", explain: "Aiko drafted angry replies but did not send them. Mira and Tomas do not describe a challenge from others." },
        { n: 52, text: "was warned that being open about a mistake could harm a career", a: "C", cue: "admitting error would damage my career", explain: "Some colleagues warned Aiko that admitting error would damage her career. In fact her grants went better." },
        { n: 53, text: "uses personal experience to prepare students for the possibility of failure", a: "C", cue: "students should learn about failure before they experience it", explain: "Aiko gives a lecture so students learn about failure early. Mira only insists on backups, which is a different matter." },
        { n: 54, text: "changed an earlier assumption about who can supply useful knowledge", a: "D", cue: "regarded local people as a source of permission rather than of knowledge", explain: "Samuel admits he used to see villagers only as people who gave permission. Their notes then became the basis of his paper." },
        { n: 55, text: "shares credit with non-specialists in a way some peers find odd", a: "D", cue: "We now share authorship", explain: "Samuel now shares authorship, which some peers consider eccentric. No other writer shares credit." },
        { n: 56, text: "was surprised by the calm reaction of people affected by the same disaster", a: "D", cue: "They had seen floods before", explain: "The villagers were not devastated as Samuel was, because they had seen floods before. The other writers did not face a natural disaster." },
      ] },
      { n: 9, type: "essay", min_words: 220, minutes_hint: 45, prompt: "In your English class you have been discussing how public money should be spent. Now your teacher has asked you to write an essay. Write an essay discussing TWO of the points below. You should explain which point you think is more important and give reasons for your point of view.\n\nEssay question: \"Governments should invest more in preserving traditional crafts than in developing new technology.\" Do you agree?\n\nNotes. Write about: 1. the effect on cultural identity; 2. the effect on employment and the economy; 3. (your own idea). Write your essay in 220–260 words.", points: ["discuss the effect on cultural identity", "discuss the effect on employment and the economy", "add your own idea"], checks: [["cultur", "identity", "heritage", "tradition"], ["employ", "job", "econom", "income"], ["educat", "tourism", "environment", "sustainab", "innovat", "apprentic"]], model: "It is tempting to see traditional crafts and new technology as rivals competing for the same public money. In my view, however, a government that neglects either of them will regret it, although there is a strong case for giving crafts more support than they currently receive.\nThe most compelling argument concerns cultural identity. Skills such as weaving, boat-building or stone carving carry the memory of a community, and once the last master has retired, that knowledge is almost impossible to recover. Furthermore, visitors are increasingly drawn to places that can offer something authentic, so heritage also strengthens a region's appeal.\nAs far as employment is concerned, the picture is more complicated. Technology companies create large numbers of well-paid jobs, whereas craft workshops are usually small and fragile. Nevertheless, they provide work in rural areas where few other employers exist, and consequently they help to keep young people from leaving.\nA further point deserves attention: education. If schools offered apprenticeships in traditional skills alongside coding, pupils would learn that creativity takes many forms. Craftspeople are, after all, often the first to adopt innovations that improve their work, such as digital design tools.\nTo sum up, governments should not have to choose between the old and the new. A modest, well-targeted fund for crafts, paid for from the growth in the technology budget rather than from cuts, would protect our heritage without slowing progress.", tips: ["Discuss two points in depth and add your own idea; do not list them.", "Say clearly which point is more important, and why.", "Keep a formal, balanced tone with a clear opening and conclusion.", "Use a range of linkers: however, whereas, nevertheless, consequently, furthermore."] },
      { n: 10, type: "proposal", min_words: 220, minutes_hint: 45, prompt: "Your local council plans to turn an empty railway building into a facility for the community and has asked residents for ideas. Write a proposal for the council. In your proposal you should say what facility you recommend, explain why it is needed, and suggest how it could be funded. Write your proposal in 220–260 words.", points: ["say what facility you recommend", "explain why it is needed", "suggest how it could be funded"], checks: [["workshop", "centre", "studio", "library", "hall"], ["need", "lack", "isolat", "shortage", "demand"], ["fund", "grant", "fee", "sponsor", "donat", "membership"]], model: "Proposal: a community workshop in the old Station Building\nIntroduction\nThe purpose of this proposal is to recommend that the empty Station Building be converted into a community workshop, open to residents of all ages. It is based on conversations with local families, clubs and shopkeepers.\nWhy the facility is needed\nAt present, our town has no affordable place where people can learn practical skills or work on projects together. Young people in particular have few options outside school hours, while many retired residents say they feel isolated. Moreover, the nearest comparable centre is forty kilometres away, which makes it unrealistic for most households.\nWhat the centre would offer\nThe ground floor could house carpentry, sewing and repair workshops, and the upper floor a small studio and a cafe. For instance, volunteers could run weekly sessions in which older residents teach traditional skills to teenagers, consequently strengthening links between generations.\nFunding\nAlthough the conversion will require an initial investment, running costs could be covered largely by membership fees, cafe income and the hire of rooms to local businesses. In addition, national heritage grants are available for the restoration of historic buildings, and several local firms have already offered to sponsor equipment.\nRecommendation\nI therefore urge the council to approve the project. It would transform an eyesore into a lively asset, and it would do so at modest cost to the taxpayer.", tips: ["Use headings: introduction, the need, the facility, funding, recommendation.", "Keep a formal, persuasive tone; recommend rather than describe.", "Support every suggestion with a reason or an example.", "Use linkers: moreover, in addition, consequently, therefore, for instance."] },
    ] },
  listening: { parts: [
      { n: 1, type: "mcq", instr: "You will hear three different extracts. For questions 1-6, choose the answer (A, B or C) which fits best according to what you hear. There are two questions for each extract. You will hear each recording twice.", units: [
        { speakers: { M: { name: "Man", accent: "en-GB", gender: "m" }, W: { name: "Woman", accent: "en-GB", gender: "f" } }, script: [
          { say: "Extract one. You hear two colleagues discussing a presentation the man gave." },
          { s: "M", t: "I thought I'd prepared well, but halfway through, the slides just froze. I stood there for what felt like ten minutes." },
          { s: "W", t: "It was about thirty seconds, honestly. Most of the room hardly noticed, and you carried on very calmly." },
          { s: "M", t: "I suppose. What bothers me is that I'd only tested the file on my own laptop, never on the room's equipment." },
          { s: "W", t: "Then next time, ask the technician to run through it beforehand. And perhaps keep a printed copy as a backup." },
        ], items: [
          { n: 1, q: "What does the man regret about the presentation?", options: ["He had not rehearsed what he was going to say.", "He had not checked the equipment in advance.", "He had lost his notes at the last moment."], a: 1, cue: "I'd only tested the file on my own laptop", explain: "He admits he only tested the file on his own laptop, not the room's equipment. Nobody mentions his rehearsal or any lost notes." },
          { n: 2, q: "What is the woman's opinion of the incident?", options: ["It changed what colleagues think of him.", "It was less noticeable than he imagines.", "It happened because he was nervous."], a: 1, cue: "Most of the room hardly noticed", explain: "She says it lasted only thirty seconds and most people hardly noticed. She does not mention his reputation or nerves." },
        ] },
        { speakers: { W: { name: "Woman", accent: "en-GB", gender: "f" } }, script: [
          { say: "Extract two. You hear a woman talking about taking up pottery after she retired." },
          { s: "W", t: "I'd never touched clay until I retired. The house was far too quiet, so a neighbour dragged me along to a class. I assumed I'd hate it, but within a week I was hooked. People imagine the difficult part is making something beautiful. For me, it's patience. You spend days shaping a bowl, and then it cracks in the kiln, and you have to start again. I'm slowly learning to shrug and laugh." },
        ], items: [
          { n: 3, q: "Why did she first go to a pottery class?", options: ["She had always wanted to try it.", "A neighbour encouraged her to attend.", "Her doctor advised her to find a hobby."], a: 1, cue: "a neighbour dragged me along to a class", explain: "A neighbour dragged her along to the class. She had never touched clay before, and no doctor is mentioned." },
          { n: 4, q: "What does she find most difficult about pottery?", options: ["producing attractive designs", "staying patient when work is ruined", "finding enough time to practise"], a: 1, cue: "For me, it's patience", explain: "She says patience is the hard part, because a bowl can crack in the kiln after days of work. Making something beautiful is not her main problem." },
        ] },
        { speakers: { P: { name: "Presenter", accent: "en-GB", gender: "m" }, L: { name: "Dr Lewis", accent: "en-GB", gender: "f" } }, script: [
          { say: "Extract three. You hear a radio presenter interviewing a scientist about birds in cities." },
          { s: "P", t: "Dr Lewis, your study suggests birds in cities sing at a higher pitch. Is that simply to be heard over the traffic?" },
          { s: "L", t: "That was our first assumption, and it's partly right. But what surprised us was that the birds raised their pitch even in quiet parks on a Sunday, which suggests the habit is being passed down from parent to chick rather than chosen afresh each morning." },
          { s: "P", t: "So is it harmful to them?" },
          { s: "L", t: "Not necessarily. Females seem to respond perfectly well to the higher songs. Where I do worry is the effect on the species that cannot adapt, such as the larger woodland birds, because they are quietly disappearing from the city." },
        ], items: [
          { n: 5, q: "What surprised the researchers?", options: ["Birds sang higher in places with little noise.", "Birds sang much louder at weekends.", "Birds copied the sounds of traffic."], a: 0, cue: "even in quiet parks on a Sunday", explain: "The birds still sang at a higher pitch in quiet parks, which suggests a learned habit. Traffic noise was only the first assumption." },
          { n: 6, q: "What is Dr Lewis most concerned about?", options: ["the stress that the change causes city birds", "the decline of birds that cannot adapt", "the failure of birds to attract partners"], a: 1, cue: "the species that cannot adapt", explain: "She worries about species that cannot adapt and are disappearing. She says females respond well to the higher songs, so attracting partners is not the problem." },
        ] },
      ] },
      { n: 2, type: "sentence", instr: "You will hear a man called Daniel Okafor giving a talk about a rooftop farm. For questions 7-14, complete the sentences with a word or short phrase. You will hear the recording twice.", units: [
        { title: "Skyline Farm", speakers: { D: { name: "Daniel", accent: "en-GB", gender: "m" } }, script: [
          { say: "Part Two. You will hear a man called Daniel Okafor giving a talk about a rooftop farm." },
          { s: "D", t: "Good evening, everyone, and thank you for coming. My name is Daniel Okafor, and I'm the project manager of Skyline Farm, the vegetable garden you may have noticed on top of the old textile warehouse near the railway station." },
          { s: "D", t: "The idea came to me about six years ago, when I was working as an architect and realised how many flat roofs in our city were completely unused. I persuaded the owner of the warehouse to lend us the space, and we began with just forty wooden boxes of soil." },
          { s: "D", t: "The biggest early problem was weight. Engineers warned us that wet soil is extremely heavy, so we switched to a lightweight growing mixture made mostly from coconut fibre, which weighs about a quarter as much." },
          { s: "D", t: "We now grow around thirty varieties of salad leaves, herbs and tomatoes, but our most profitable crop by far is rocket. It grows quickly, even in cool weather, and chefs love its peppery flavour." },
          { s: "D", t: "That brings me to our customers. Roughly sixty per cent of everything we produce goes to restaurants within two miles of the farm, which means it is on a plate within hours of being picked. The rest is sold at our stall every Saturday morning, and as you can imagine, the queue starts early." },
          { s: "D", t: "Local people have been wonderfully supportive, too. Each month a group of retired neighbours comes up to help with the weeding, and in return they take home a bag of whatever is ripe. It has turned a rather lonely rooftop into something much closer to a village allotment, and I think that sense of community is just as valuable as the vegetables." },
          { s: "D", t: "We also keep four hives of bees on the roof, and the honey has become a small business of its own. The bees also help pollinate the tomatoes, so they more than earn their keep." },
          { s: "D", t: "Of course, a roof is not an easy place to farm. Last winter the wind was a real problem, and it flattened a whole row of young plants. We have since built tall wooden windbreaks along the edge, and the damage has stopped." },
          { s: "D", t: "Looking ahead, our dream is to open a small café up here next spring, so that visitors can eat what they see growing around them. We've already applied for the licence, and I'll be happy to tell you more at the end if you have any questions." },
        ], items: [
          { n: 7, text: "The farm began with ___ wooden boxes of soil.", a: ["forty", "40"], cue: "just forty wooden boxes of soil", explain: "Daniel says they began with just forty wooden boxes of soil." },
          { n: 8, text: "The lightweight growing mixture is made mostly from ___ fibre.", a: ["coconut"], cue: "made mostly from coconut fibre", explain: "To reduce weight they switched to a mixture made mostly from coconut fibre." },
          { n: 9, text: "The farm's most profitable crop is ___.", a: ["rocket"], cue: "our most profitable crop by far is rocket", explain: "Salad leaves, herbs and tomatoes are also grown, but rocket is the most profitable crop." },
          { n: 10, text: "About ___ per cent of the produce is sold to restaurants.", a: ["sixty", "60"], cue: "Roughly sixty per cent of everything we produce", explain: "Roughly sixty per cent goes to restaurants. The thirty is the number of varieties grown." },
          { n: 11, text: "The farm has a stall which opens every ___ morning.", a: ["Saturday", "Saturdays"], cue: "at our stall every Saturday morning", explain: "The rest of the produce is sold at the stall every Saturday morning." },
          { n: 12, text: "The roof is home to ___ hives of bees.", a: ["four", "4"], cue: "We also keep four hives of bees", explain: "Daniel says they keep four hives of bees on the roof." },
          { n: 13, text: "Last winter's damage led to the building of wooden ___.", a: ["windbreaks", "wind breaks", "windbreak"], cue: "built tall wooden windbreaks along the edge", explain: "After the wind flattened plants they built tall wooden windbreaks." },
          { n: 14, text: "Next spring the project hopes to open a ___ on the roof.", a: ["café", "cafe"], cue: "to open a small café up here next spring", explain: "The dream for next spring is to open a small café on the roof." },
        ] },
      ] },
      { n: 3, type: "mcq", instr: "You will hear an interview with a woman called Priya Nair, who makes violins. For questions 15-20, choose the answer (A, B, C or D) which fits best according to what you hear. You will hear the recording twice.", units: [
        { title: "Interview with Priya Nair", speakers: { P: { name: "Presenter", accent: "en-GB", gender: "m" }, N: { name: "Priya", accent: "en-GB", gender: "f" } }, script: [
          { say: "Part Three. You will hear an interview with a woman called Priya Nair, who gave up a career as a professional violinist to make violins." },
          { s: "P", t: "My guest this week is Priya Nair, who gave up a career as a professional violinist to become an instrument maker. Priya, most musicians would call that a strange move." },
          { s: "N", t: "People assume it was an injury, but actually my hands were fine. The truth is that I had started to feel I was a very small part of a very large machine. In an orchestra of eighty, nobody hears you individually, and I wanted to make something that was undeniably mine." },
          { s: "P", t: "And how did you learn the craft? I imagine there aren't many schools." },
          { s: "N", t: "There are a few, but I didn't go to one. I wrote to a maker in Cremona, a man in his seventies, and he refused me three times. The fourth time, I simply turned up with a packed lunch and sat outside his workshop until he let me in." },
          { s: "P", t: "What was the first year like?" },
          { s: "N", t: "Humbling. For the first six months, I did nothing but sharpen tools and sweep up wood shavings. I was furious, but later I realised he was showing me how much of the craft is preparation. Making a violin takes about three hundred hours, and perhaps a third of that is simply getting the materials right." },
          { s: "P", t: "Do players treat a new instrument differently from an old Italian violin?" },
          { s: "N", t: "There's a lot of snobbery, certainly. But in blind tests, even professionals often prefer modern instruments, and they're usually shocked. What I'd say is that an old violin comes with a story, and that story affects how it sounds to the player's ear, if not to the audience's." },
          { s: "P", t: "What is the hardest part of running a workshop?" },
          { s: "N", t: "Honestly, the business side. I can spend three weeks carving a scroll perfectly, and then realise I haven't answered an email in a month. A friend now does my accounts, and I've promised not to open my inbox before noon. If I could hire somebody to answer the phone as well, I'd be happy." },
          { s: "P", t: "You have no formal qualification in the field. Has that ever held you back?" },
          { s: "N", t: "Not once. Customers want to know whether the violin sounds good, not whether I have a certificate on the wall. Early on, a few older makers were rather dismissive, but most of them came round when they heard my instruments being played in public, and some are now good friends." },
          { s: "P", t: "And what about the future?" },
          { s: "N", t: "I'm starting to teach. A young woman has just joined me as an apprentice, and I've caught myself being strict about sweeping the floor. I can hear my old teacher in my own voice. I want her to see the whole process, but also to enjoy it more than I did at first." },
        ], items: [
          { n: 15, q: "Why did Priya stop playing professionally?", options: ["She had damaged her hands.", "She felt her individual contribution was lost.", "She disliked travelling so much.", "She was offered a better job."], a: 1, cue: "a very small part of a very large machine", explain: "She felt like a very small part of a large machine and wanted to make something of her own. She says people wrongly assume it was an injury." },
          { n: 16, q: "How did Priya get her training?", options: ["at a specialist college", "by persuading an established maker to accept her", "through a government scheme", "by teaching herself from books"], a: 1, cue: "sat outside his workshop until he let me in", explain: "She kept asking a maker in Cremona until he let her in. She says she did not go to one of the few schools." },
          { n: 17, q: "What did Priya learn from her early months in the workshop?", options: ["Her earlier skills were of little use.", "Preparation is a large part of the work.", "Her teacher was unreasonably strict.", "Tools matter more than materials."], a: 1, cue: "how much of the craft is preparation", explain: "She realised that preparation is a big part of the craft. She was furious at first, but later understood her teacher's reasons." },
          { n: 18, q: "What does Priya say about old Italian violins?", options: ["They sound better than new ones to audiences.", "Their reputation influences how players hear them.", "Professionals refuse to try modern instruments.", "They are less reliable than people think."], a: 1, cue: "that story affects how it sounds to the player's ear", explain: "The story of an old violin affects how it sounds to the player. In blind tests professionals often prefer modern instruments, so option A is wrong." },
          { n: 19, q: "What does Priya find hardest about running her workshop?", options: ["finding enough skilled assistants", "keeping up with demand", "persuading musicians to try new instruments", "dealing with administrative tasks"], a: 3, cue: "the business side", explain: "She says the business side is hardest, for example not answering emails for a month. She does not mention a lack of customers or assistants." },
          { n: 20, q: "How does Priya feel about taking on an apprentice?", options: ["nervous about her ability to teach", "amused to notice she is copying her own teacher", "worried that the apprentice will become a rival", "eager to make the training much shorter"], a: 1, cue: "I can hear my old teacher in my own voice", explain: "She notices she sounds like her old teacher, which amuses her. She wants the apprentice to enjoy training more, not to shorten it." },
        ] },
      ] },
      { n: 4, type: "matching", instr: "You will hear five short extracts in which people are talking about each of two topics. In Task One (questions 21-25) choose from the list (A-H) what each speaker found most rewarding about volunteering abroad. In Task Two (questions 26-30) choose from the list (A-H) the main drawback each speaker mentions about working from home. Use the letters only once in each task. There are three extra letters in each task which you do not need to use. You will hear the recording twice.", units: [
        { title: "Task One: volunteering abroad", options: ["A being pushed beyond what they thought they could do", "B discovering a very different way of life", "C forming friendships that have lasted", "D gaining skills useful for their career", "E realising how fortunate they are at home", "F seeing a project continue after they left", "G picking up another language", "H earning the respect of local people"],
          speakers: { N: { name: "Narrator", accent: "en-GB", gender: "m" }, S1: { name: "Speaker 1", accent: "en-GB", gender: "f" }, S2: { name: "Speaker 2", accent: "en-GB", gender: "m" }, S3: { name: "Speaker 3", accent: "en-GB", gender: "f" }, S4: { name: "Speaker 4", accent: "en-GB", gender: "m" }, S5: { name: "Speaker 5", accent: "en-GB", gender: "f" } },
          script: [
            { say: "Part Four. Task One. You will hear five people talking about volunteering abroad. What did each of them find most rewarding?" },
            { say: "Speaker 1" },
            { s: "S1", t: "I'll admit I went mostly to put something on my CV. I ended up managing a team of twelve on a building scheme and handling the budget, which I'd never done before. Employers ask me about it at every interview now. The locals were lovely, of course, but that wasn't why I went." },
            { say: "Speaker 2" },
            { s: "S2", t: "We built a small clinic in a mountain village, and I assumed it would fall into disrepair once the money ran out. Then last year, a former colleague sent me photographs. The villagers are still running it, and they've even added a waiting room. That's what I'm proudest of." },
            { say: "Speaker 3" },
            { s: "S3", t: "I'm not sporty, so when they asked me to lead a group of teenagers on a three-day trek, I nearly refused. I did it, with blisters and plenty of doubt, and I came home knowing I could cope with far more than I'd ever have guessed." },
            { say: "Speaker 4" },
            { s: "S4", t: "People assume the work is what stays with you, but for me it's the lads I shared a dormitory with. We're scattered across four countries now, yet we speak every week, and one of them was best man at my wedding." },
            { say: "Speaker 5" },
            { s: "S5", t: "I arrived with a phrasebook and very little confidence. By the end of six months, I was bargaining in the market and even telling jokes in the local dialect. I hadn't expected to get that far, and I've carried on with lessons ever since." },
          ],
          items: [
            { n: 21, text: "Speaker 1", a: "D", cue: "Employers ask me about it at every interview now", explain: "She managed a team and a budget, which employers value. She says the locals were not her reason for going." },
            { n: 22, text: "Speaker 2", a: "F", cue: "The villagers are still running it", explain: "He is proudest that the clinic still runs without him. He had feared it would fall into disrepair." },
            { n: 23, text: "Speaker 3", a: "A", cue: "I could cope with far more than I'd ever have guessed", explain: "Leading the trek showed her she could do more than she expected. She is not sporty, so this was a real stretch." },
            { n: 24, text: "Speaker 4", a: "C", cue: "we speak every week", explain: "He values the people he shared a dormitory with, who still keep in touch. The work itself is not what stays with him." },
            { n: 25, text: "Speaker 5", a: "G", cue: "telling jokes in the local dialect", explain: "She learnt enough of the local speech to bargain and tell jokes, and she still takes lessons." },
          ] },
        { title: "Task Two: working from home", options: ["A difficulty switching off at the end of the day", "B missing casual conversations with colleagues", "C working in a noisy space", "D being overlooked for promotion", "E problems with technology", "F being tempted to do housework", "G higher household bills", "H feeling guilty about taking breaks"],
          speakers: { N: { name: "Narrator", accent: "en-GB", gender: "f" }, S1: { name: "Speaker 1", accent: "en-GB", gender: "m" }, S2: { name: "Speaker 2", accent: "en-GB", gender: "f" }, S3: { name: "Speaker 3", accent: "en-GB", gender: "m" }, S4: { name: "Speaker 4", accent: "en-GB", gender: "f" }, S5: { name: "Speaker 5", accent: "en-GB", gender: "m" } },
          script: [
            { say: "Task Two. You will hear five people talking about working from home. What is the main drawback each of them mentions?" },
            { say: "Speaker 1" },
            { s: "S1", t: "My laptop lives on the kitchen table, and that's the trouble. At six o'clock I mean to stop, but an email pings and suddenly it's nine. Nobody tells you that the office door at least gave you a natural end to the day." },
            { say: "Speaker 2" },
            { s: "S2", t: "I'm productive, no question, and my broadband is excellent. But when my manager handed out the new team-leader posts, I wasn't even considered, and I think it's simply because she hardly ever sees me. Out of sight, out of mind." },
            { say: "Speaker 3" },
            { s: "S3", t: "I thought I'd love the peace. What I hadn't counted on was missing the chat by the coffee machine, the small jokes, the quick questions. Video calls are efficient, but nobody has a laugh on them." },
            { say: "Speaker 4" },
            { s: "S4", t: "The bills have been a shock. Heating a house all day costs far more than I'd budgeted, and my employer pays nothing towards it. I wear two jumpers rather than turn up the radiator." },
            { say: "Speaker 5" },
            { s: "S5", t: "I share a small flat with two people who also work from home, and we're all on calls at once. Somebody is always shouting 'can you hear me?' in the next room. I've started wearing headphones just to hear myself think." },
          ],
          items: [
            { n: 26, text: "Speaker 1", a: "A", cue: "At six o'clock I mean to stop, but an email pings and suddenly it's nine", explain: "He cannot stop working in the evening because the laptop is always there. He says nothing about his equipment failing." },
            { n: 27, text: "Speaker 2", a: "D", cue: "I wasn't even considered", explain: "She was not considered for a team-leader post because her manager rarely sees her. Her broadband is excellent, so technology is not the issue." },
            { n: 28, text: "Speaker 3", a: "B", cue: "missing the chat by the coffee machine", explain: "He misses the informal chat and jokes with colleagues. Video calls do not replace them." },
            { n: 29, text: "Speaker 4", a: "G", cue: "costs far more than I'd budgeted", explain: "She is shocked by the cost of heating all day, which her employer does not cover." },
            { n: 30, text: "Speaker 5", a: "C", cue: "we're all on calls at once", explain: "The people in his flat are all on calls at once, so it is hard to concentrate. He wears headphones to cope." },
          ] },
      ] },
    ] },
  speaking: { parts: [
     { n: 1, type: "interview", minutes: [2, 3], phases: [
        { q: ["What's your name?", "Where are you from?", "Do you work or are you a student?", "What do you enjoy most about living there?"] },
        { topic: "Work and study", q: ["How important is it to you to enjoy the work or studies you do?", "What do you think makes a good colleague or classmate?", "Do you think people should change careers more than once in their lives?"], extended: "Tell me about a challenge you faced recently and how you dealt with it." },
        { topic: "Technology and daily life", q: ["How has technology changed the way you spend your day?", "Do you think people rely too much on their phones?", "Is there any piece of technology you could happily live without?"], extended: "Tell me about a time when new technology made something much easier for you." },
      ], models: {
        "What's your name?": "My name is Linh, and I'm happy to be here today. I have been preparing for this exam for almost a year, so I feel quite confident, although I admit that I am also a little nervous, as anybody would be at this stage. Please call me Linh if you like.",
        "Where are you from?": "I come from a medium-sized city on the coast, about three hours south of the capital. It is a lively place with a long history as a port, and I have lived there since I was born, apart from two years abroad. I would recommend it to anyone who loves seafood.",
        "Do you work or are you a student?": "I'm a graduate student at the moment, and I am doing a master's degree in environmental science. I also work part-time as a research assistant, which is demanding, but it gives me valuable experience that I can use after I graduate. I hope to start a full-time job next year.",
        "What do you enjoy most about living there?": "What I enjoy most is the balance between city life and nature. I can walk to the beach in ten minutes, yet there are plenty of cafes, galleries and concerts nearby, so I never feel that I am missing out on anything. The people are friendly too.",
        "How important is it to you to enjoy the work or studies you do?": "It is extremely important to me. If I don't find a subject stimulating, I quickly lose motivation, and my results suffer. I would rather earn a little less money in a job I find meaningful than spend forty years doing something that bores me. Enjoyment simply makes hard work feel worthwhile, and it keeps me going.",
        "What do you think makes a good colleague or classmate?": "In my view, a good colleague is someone who is reliable and willing to share ideas without trying to take all the credit. A sense of humour helps as well, because it keeps the atmosphere positive when deadlines are tight and everybody is under pressure. Honesty matters too, in my opinion.",
        "Do you think people should change careers more than once in their lives?": "I think it can be a healthy thing to do, provided you plan carefully. Jobs are changing so fast that skills become outdated, and a fresh start can bring new energy. However, moving too often might make it hard to build real expertise. Ultimately, it really depends on the person and the field.",
        "Tell me about a challenge you faced recently and how you dealt with it.": "Recently I had to lead a group project with people I barely knew, and we disagreed about almost everything at first. Rather than imposing my own plan, I organised a meeting where everyone explained their priorities. That made the atmosphere calmer, and we eventually delivered a result we were all proud of.",
        "How has technology changed the way you spend your day?": "Quite dramatically. I used to need a whole morning to go to the library, whereas now I can read most articles online in minutes. On the other hand, I am constantly distracted by notifications, so I sometimes have to switch my phone off in order to concentrate. Overall, I think the benefits outweigh the costs.",
        "Do you think people rely too much on their phones?": "Generally speaking, yes. Many people cannot even wait for a bus without checking their screens, and that habit has weakened face-to-face conversation. Phones are undeniably useful, of course, but I believe we should be more selective about when we use them. Moderation is the key, in my view.",
        "Is there any piece of technology you could happily live without?": "I could happily live without social media. It takes up an enormous amount of time, and a lot of what you see is carefully edited, which can make you feel dissatisfied with your own life. I would miss messaging apps far more, since they keep me in touch with family. Staying in touch matters more to me than entertainment.",
        "Tell me about a time when new technology made something much easier for you.": "Last year I moved to a new country, and a translation app saved me on my first day. I had to sign a rental contract in a language I barely spoke, and the app let me understand every clause. Without it, I would probably have made a costly mistake.",
      }, tips: ["Give reasons and examples, not just short answers; aim for four or five sentences.", "For 'Tell me about...' include what happened, who was involved, and what you learned.", "Use a range of structures: conditionals, comparisons, and linking phrases such as 'on the other hand'."] },
      { n: 2, type: "long-turn", minutes: [3, 4], prompt: "Here are two photographs. They show people making an important decision. Compare the photographs and say what might influence each decision and how difficult each decision might be.", options: [{ ic: "🎓", label: "Photo A: a young woman reading university brochures at a desk, surrounded by papers" }, { ic: "🏠", label: "Photo B: a couple looking at a house with an estate agent" }], follow: ["Which of these decisions do you think would be harder to make?", "Do you ask other people for advice when you have to make a big decision?", "Is it better to decide quickly or to take plenty of time?"], models: {
        "Here are two photographs. They show people making an important decision. Compare the photographs and say what might influence each decision and how difficult each decision might be.": "Both photographs show people at a turning point, but the decisions are rather different. In the first, a young woman seems to be choosing a university course, so her choice will probably be influenced by her interests, her career plans and what her family expects. In the second, a couple is considering buying a house, and money is likely to be the deciding factor, along with location and space. I imagine the second decision is the harder one, because it involves a huge financial commitment and two people who must agree, whereas the student, although under pressure, can still change course later if she makes a mistake. In short, both decisions matter, but their scale and reversibility differ greatly.",
        "Which of these decisions do you think would be harder to make?": "I think buying a house is harder, because it is expensive and difficult to reverse. A course can be changed, but a mortgage may affect you for decades, so mistakes have much more serious consequences.",
        "Do you ask other people for advice when you have to make a big decision?": "Usually I do. I talk to a couple of people I trust, because they often notice risks I have missed. In the end, though, I make the final choice myself, since I am the one who will live with it.",
        "Is it better to decide quickly or to take plenty of time?": "It depends on the situation. For major decisions, I prefer to take my time and gather information. However, thinking for too long can be harmful, because opportunities disappear and you may simply become more anxious.",
      }, useful: ["Both photos show ... but in the first one ...", "Whereas ... seems to be ..., the other ...", "This decision is likely to be influenced by ...", "I imagine / It could be that ...", "The more difficult of the two is probably ..."], tips: ["Compare and contrast; do not describe each picture in turn for too long.", "Answer both parts of the question on the card, including how difficult each decision might be.", "Speculate with modal verbs and phrases such as 'she might be' and 'I imagine'."] },
      { n: 3, type: "collaborative", minutes: [3, 4], prompt: "A university wants to prepare its students better for working life. Here are some ideas. Talk together about how useful each idea might be for students and then decide which one the university should introduce first.", options: [{ ic: "🏢", label: "compulsory work placements with local companies" }, { ic: "🤝", label: "a mentoring scheme with former students" }, { ic: "💬", label: "courses in communication and teamwork" }, { ic: "💻", label: "training in digital skills" }, { ic: "🎤", label: "regular talks by guest speakers from industry" }], partnerLines: ["Work placements seem the most practical to me. Students would see the job for real.", "True, but could every student find a placement? Some companies might not have space.", "I like the mentoring idea. Having someone to ask for advice must be reassuring.", "Digital skills are important, though perhaps students learn those on their own anyway.", "Guest talks are cheap and easy to arrange, but are they really that useful?", "So, which one shall we put first, do you think?"], follow: ["Which idea do you think would cost the university the most?", "What would you say is the biggest difference between studying and working?", "Which idea would you have found most useful yourself?"], models: {
        "A university wants to prepare its students better for working life. Here are some ideas. Talk together about how useful each idea might be for students and then decide which one the university should introduce first.": "I think work placements would be extremely valuable, because students would gain real experience and learn how an office actually functions. The difficulty is that the university would need agreements with a lot of companies. Training in digital skills is also useful, although many students already have those. Personally, I would start with the mentoring scheme, since it is cheap and gives students advice from people who have been in their position. Do you agree, or would you put placements first?",
        "Which idea do you think would cost the university the most?": "Probably the work placements, since staff would have to find companies, check conditions and supervise students. Guest talks would cost much less, as speakers often come for free. Overall, I would say the difference is quite large.",
        "What would you say is the biggest difference between studying and working?": "At work you are responsible for results that affect other people, whereas at university mistakes mainly affect your own grades. Also, work has less flexibility, because deadlines are set by others. That is the contrast I noticed most when I did an internship.",
        "Which idea would you have found most useful yourself?": "I would have found a mentor most useful. I often felt unsure about which direction to take, and a person with experience could have helped me avoid some wrong decisions. That is why I would support it for future students.",
      }, useful: ["How useful would ... be for students?", "One advantage of ... is that ...", "I'm not entirely convinced that ...", "That's a fair point, but surely ...?", "Shall we agree that ... should come first?"], tips: ["Discuss every option briefly before you decide; do not choose too early.", "Invite your partner's opinion and respond to what they say.", "Then, for the decision question, reach an agreement together."] },
      { n: 4, type: "discussion", minutes: [3, 4], prompt: "Do you think technology has made people's lives better or just busier?", follow: ["Some people say that working from home improves quality of life. What is your view?", "How far should governments control what children see on the internet?", "Do you think we will ever be able to trust machines to make important decisions for us?"], models: {
        "Do you think technology has made people's lives better or just busier?": "I would say both. Technology has made many tasks quicker and has given us access to knowledge that was previously out of reach. At the same time, because we can always be contacted, the line between work and rest has become blurred, so many people feel they are never really off duty. Ultimately, it depends on how disciplined each person is. Personally, I try to switch off my devices every evening.",
        "Some people say that working from home improves quality of life. What is your view?": "It certainly can, since you save the time and money spent on commuting and you have more control over your day. However, it can also be isolating, and some people find it hard to concentrate at home. A mixture of office and home working seems the most sensible solution for most people. Personally, I work best with some variety in my week.",
        "How far should governments control what children see on the internet?": "I think governments should set basic rules, such as age limits for harmful content, but parents and schools must play the main role. Strict control is difficult to enforce, and children are skilled at finding ways round restrictions, so teaching them to think critically is more effective in the long run. Education, in my view, is a better safeguard than prohibition.",
        "Do you think we will ever be able to trust machines to make important decisions for us?": "In limited areas, perhaps. Machines can analyse medical data faster than any doctor, for example. Even so, I believe a person should always be accountable for final decisions, because machines cannot understand human values, and when something goes wrong, someone has to take responsibility. Trust has to be earned, and so far machines have only partly earned it, so human oversight must remain.",
      }, useful: ["I'd say it cuts both ways ...", "There's no doubt that ...", "That said, we shouldn't overlook ...", "To a certain extent, I agree, but ...", "In the long run, I believe ..."] },
    ] },
});
